import{_ as i,o as t,c as s,a4 as e}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"Fcitx5 + Edge + KDE Wayland 输入法踩坑记录","description":"","frontmatter":{"title":"Fcitx5 + Edge + KDE Wayland 输入法踩坑记录","date":"2026-07-22T00:00:00.000Z"},"headers":[],"relativePath":"posts/fcitx5-edge-wayland-踩坑记录.md","filePath":"posts/fcitx5-edge-wayland-踩坑记录.md"}'),n={name:"posts/fcitx5-edge-wayland-踩坑记录.md"};function l(d,a,o,r,h,p){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="fcitx5-edge-kde-wayland-输入法踩坑记录" tabindex="-1">Fcitx5 + Edge + KDE Wayland 输入法踩坑记录 <a class="header-anchor" href="#fcitx5-edge-kde-wayland-输入法踩坑记录" aria-label="Permalink to &quot;Fcitx5 + Edge + KDE Wayland 输入法踩坑记录&quot;">​</a></h1><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li>系统: Debian 13 (trixie), KDE Plasma 6.3.6, KWin 6.3.6</li><li>显示协议: Wayland</li><li>浏览器: Microsoft Edge 150.0.4078.83 (deb 安装)</li><li>输入法: fcitx5 + rime</li></ul><hr><h2 id="探索轨迹-按时间顺序" tabindex="-1">探索轨迹（按时间顺序） <a class="header-anchor" href="#探索轨迹-按时间顺序" aria-label="Permalink to &quot;探索轨迹（按时间顺序）&quot;">​</a></h2><h3 id="第-1-轮-猜参数" tabindex="-1">第 1 轮：猜参数 <a class="header-anchor" href="#第-1-轮-猜参数" aria-label="Permalink to &quot;第 1 轮：猜参数&quot;">​</a></h3><p>现象：Edge 打不出中文，其他 App 正常。 猜：缺启动参数。</p><p>尝试：</p><ol><li><code>--gtk-version=4</code> → 没用。Edge 的 UI 部分 (地址栏、菜单) 用 GTK，但<strong>网页内容 IME 走 Chromium 自己的 IME 栈</strong>，不归 GTK 管。</li><li><code>--ozone-platform=wayland --enable-wayland-ime</code> → 还是没用。</li><li><code>--gtk-version=4</code> 换成 <code>--ozone-platform=wayland</code> → 没用。</li></ol><p>此时以为是参数不对，不断换方案。</p><h3 id="第-2-轮-怀疑环境变量" tabindex="-1">第 2 轮：怀疑环境变量 <a class="header-anchor" href="#第-2-轮-怀疑环境变量" aria-label="Permalink to &quot;第 2 轮：怀疑环境变量&quot;">​</a></h3><p>猜：<code>GTK_IM_MODULE=fcitx</code> 跟 Wayland 冲突。</p><p>操作：</p><ul><li>建 <code>~/.config/environment.d/fcitx5.conf</code> 清掉 <code>GTK_IM_MODULE</code></li><li>在 <code>~/.config/gtk-3.0/settings.ini</code> 和 <code>~/.gtkrc-2.0</code> 加 <code>gtk-im-module=fcitx</code></li><li>登出重进 → 还是没用</li></ul><p>结论：Edge 压根不用 GTK 路径，环境变量纯属混淆项。</p><h3 id="第-3-轮-怀疑-edge-不支持-flags-conf" tabindex="-1">第 3 轮：怀疑 Edge 不支持 flags.conf <a class="header-anchor" href="#第-3-轮-怀疑-edge-不支持-flags-conf" aria-label="Permalink to &quot;第 3 轮：怀疑 Edge 不支持 flags.conf&quot;">​</a></h3><p>试 <code>~/.config/microsoft-edge-stable-flags.conf</code> → Edge 进程命令行没读到这些参数，Edge 可能不支持这文件。</p><h3 id="第-4-轮-搜到官方文档" tabindex="-1">第 4 轮：搜到官方文档 <a class="header-anchor" href="#第-4-轮-搜到官方文档" aria-label="Permalink to &quot;第 4 轮：搜到官方文档&quot;">​</a></h3><p><a href="https://fcitx-im.org/wiki/Using_Fcitx_5_on_Wayland#KDE_Plasma" target="_blank" rel="noreferrer">https://fcitx-im.org/wiki/Using_Fcitx_5_on_Wayland#KDE_Plasma</a></p><p>官方给出的 KDE Plasma 最佳实践：</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th></tr></thead><tbody><tr><td>KDE 版本</td><td>5.27+</td></tr><tr><td>环境变量</td><td>只设 <code>XMODIFIERS=@im=fcitx</code></td></tr><tr><td>虚拟键盘</td><td>系统设置 → 虚拟键盘 → 选 <strong>Fcitx 5</strong></td></tr><tr><td>Edge 参数</td><td><code>--enable-features=UseOzonePlatform --ozone-platform=wayland --enable-wayland-ime</code></td></tr><tr><td>⚠</td><td><strong>不要手动重启 fcitx5</strong>（<code>pkill</code> / 托盘重启都不行）</td></tr></tbody></table><h3 id="第-5-轮-被自己坑了" tabindex="-1">第 5 轮：被自己坑了 <a class="header-anchor" href="#第-5-轮-被自己坑了" aria-label="Permalink to &quot;第 5 轮：被自己坑了&quot;">​</a></h3><p>我手动执行了 <code>pkill fcitx5</code> 和 <code>/usr/bin/fcitx5 -d</code> 来重启 fcitx5。</p><p>官方文档明确说：</p><blockquote><p>&quot;If you launch fcitx this way (via Virtual Keyboard KCM), make sure you do not use &#39;restart&#39; in the tray menu, since the socket passed from KWin can not be reused with the newly restarted fcitx.&quot;</p></blockquote><p>KWin 启动 fcitx5 时会传一个 Wayland socket 给它，手动重启后 socket 就断了，text-input-v3 协议整个走不通。<strong>分步试配置 + 重启 fcitx5 = 两件事互相搞死。</strong></p><h3 id="第-6-轮-最终生效" tabindex="-1">第 6 轮：最终生效 <a class="header-anchor" href="#第-6-轮-最终生效" aria-label="Permalink to &quot;第 6 轮：最终生效&quot;">​</a></h3><p>直接去 KDE 系统设置→虚拟键盘→选 Fcitx 5，<strong>即时生效，不需要登出</strong>。</p><hr><h2 id="关键链条" tabindex="-1">关键链条 <a class="header-anchor" href="#关键链条" aria-label="Permalink to &quot;关键链条&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Edge (Wayland)</span></span>
<span class="line"><span>  ↓ text-input-v3 协议</span></span>
<span class="line"><span>KWin (合成器)</span></span>
<span class="line"><span>  ↓ zwp_input_method_v1/v2 协议</span></span>
<span class="line"><span>fcitx5 (输入法后端)</span></span></code></pre></div><p>三个环节缺一不可：</p><ol><li><strong>Edge 必须走 Wayland 模式</strong>：<code>--ozone-platform=wayland --enable-wayland-ime</code></li><li><strong>KWin 必须有输入法后端</strong>：系统设置→虚拟键盘→Fcitx 5</li><li><strong>fcitx5 必须由 KWin 启动</strong>（不要手动重启）</li></ol><hr><h2 id="踩坑汇总" tabindex="-1">踩坑汇总 <a class="header-anchor" href="#踩坑汇总" aria-label="Permalink to &quot;踩坑汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>为什么错</th></tr></thead><tbody><tr><td><code>--gtk-version=4</code></td><td>网页内容 IME 不走 GTK，走 Chromium IME 栈</td></tr><tr><td>改 <code>GTK_IM_MODULE</code> 环境变量</td><td>Edge 不在乎这变量，改它纯属干扰</td></tr><tr><td><code>~/.config/*-flags.conf</code></td><td>Edge 可能不支持这个 Chromium 特性</td></tr><tr><td><code>environment.d</code> 设 <code>CHROME_EXTRA_FLAGS</code></td><td>systemd 环境注入对 KDE 菜单启动不生效</td></tr><tr><td>手动 <code>pkill fcitx5</code> / <code>fcitx5 -d</code></td><td>KWin 传的 socket 断了，text-input 协议全废</td></tr><tr><td>只改配置文件不去 GUI</td><td>可能配置文件格式不对或缺字段，GUI 操作最可靠</td></tr><tr><td>登出重进</td><td>其实不需要，虚拟键盘改了即时生效</td></tr></tbody></table><hr><h2 id="最终解决方案-一句话" tabindex="-1">最终解决方案（一句话） <a class="header-anchor" href="#最终解决方案-一句话" aria-label="Permalink to &quot;最终解决方案（一句话）&quot;">​</a></h2><blockquote><p><strong>系统设置 → 键盘 → 虚拟键盘 → 选「Fcitx 5」，Edge 桌面文件 Exec 行加 <code>--enable-features=UseOzonePlatform --ozone-platform=wayland --enable-wayland-ime</code>，不要手动重启 fcitx5。</strong></p></blockquote><hr><h2 id="其他有用的诊断命令" tabindex="-1">其他有用的诊断命令 <a class="header-anchor" href="#其他有用的诊断命令" aria-label="Permalink to &quot;其他有用的诊断命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 查看 Edge 版本</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">microsoft-edge-stable</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 检查 fcitx5 运行状态</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">pgrep</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -a</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> fcitx5</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># fcitx5 诊断（完整环境检查）</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">fcitx5-diagnose</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 检查 Edge 是否识别参数（搜二进制中的 flag 名称）</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">strings</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /opt/microsoft/msedge/msedge</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> |</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> grep</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -i</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">wayland-ime\\|ozone-platform\\|text-input</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 看 KWin 输入法配置</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">cat</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ~/.config/kwinrc</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> |</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> grep</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -A2</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">\\[Wayland\\]</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">cat</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ~/.config/kcminputrc</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> |</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> grep</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -A2</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">\\[Keyboard\\]</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span></span></code></pre></div><hr><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://fcitx-im.org/wiki/Using_Fcitx_5_on_Wayland#KDE_Plasma" target="_blank" rel="noreferrer">https://fcitx-im.org/wiki/Using_Fcitx_5_on_Wayland#KDE_Plasma</a></li><li><a href="https://github.com/notTPALT/0a180da605229294a4edc98270d9957e" target="_blank" rel="noreferrer">https://github.com/notTPALT/0a180da605229294a4edc98270d9957e</a> (KDE Wayland fix gist)</li></ul>`,45)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
